<script setup>
import { computed, onMounted, onBeforeUnmount, ref } from 'vue'
import { api } from '../utils/api'
import { themeState, themeOptions } from '../composables/useTheme'
import { useServerSocket } from '../composables/useServerSocket'
import { online } from '../utils/format'
import ServerCard from '../components/ServerCard.vue'
import StatBar from '../components/StatBar.vue'
const servers = ref([]); const loading = ref(true); const error = ref(''); const pending = new Map(); let flushTimer; let loaded = false
const stats = computed(() => themeState.config?.stats || {}); const showThreeNet = computed(() => themeState.config?.sysConfig?.show_three_net_details === true || themeState.config?.show_three_net_details === true); const networkNames = computed(() => ({ ct: themeState.config?.custom_ct_name || 'CT', cu: themeState.config?.custom_cu_name || 'CU', cm: themeState.config?.custom_cm_name || 'CM', bgp: themeState.config?.custom_bgp_name || 'BGP' })); const ids = () => servers.value.map((s) => s.id)
function mergeServer(server, patch) { const index = servers.value.findIndex((s) => String(s.id) === String(server.id)); if (index >= 0) servers.value[index] = { ...servers.value[index], ...patch } }
function onBatch(message) { (message.updates || []).forEach((update) => { const id = update.id ?? update.server_id; const latest = (update.samples || []).at(-1); const data = latest?.data || latest?.payload || latest?.metrics; if (id != null && data) pending.set(String(id), data) }); if (!flushTimer) flushTimer = setTimeout(() => { pending.forEach((patch, id) => { const old = servers.value.find((s) => String(s.id) === id); if (old) mergeServer(old, patch) }); pending.clear(); flushTimer = undefined }, 1000) }
const socket = useServerSocket('all', ids, onBatch, Number(themeState.config?.frontend_ws_timeout_minutes || 0))
async function loadServers(force = false) { if (!force && !loading.value && loaded && !document.hidden) return; loading.value = true; try { const result = await api.servers(); servers.value = result.servers || result.data || []; loaded = true } catch (e) { error.value = e.message } finally { loading.value = false } }
async function visibleChange() { if (!document.hidden) { await loadServers(true); socket.reconnect() } else socket.stop() }
onMounted(async () => { await loadServers(); socket.start(); document.addEventListener('visibilitychange', visibleChange) }); onBeforeUnmount(() => { socket.stop(); document.removeEventListener('visibilitychange', visibleChange); clearTimeout(flushTimer) })
</script>
<template><section class="page dashboard-page"><div class="hero"><div><p class="eyebrow">SYSTEM OVERVIEW</p><h1>{{ themeState.config?.site_name || 'Your infrastructure at a glance' }}</h1><p class="subtitle">Live performance insights across every node.</p></div><div class="live-indicator"><i :class="{ connected: socket.connected }" /> {{ socket.connected ? 'Live updates' : 'Reconnecting' }}</div></div><div class="stats-row"><StatBar label="TOTAL NODES" :value="stats.total ?? servers.length" detail="registered servers" /><StatBar label="ONLINE" :value="stats.online ?? servers.filter(online).length" detail="responding now" tone="green" /><StatBar label="OFFLINE" :value="stats.offline ?? Math.max(0, servers.length - servers.filter(online).length)" detail="need attention" tone="red" /></div><div v-if="error" class="notice error">{{ error }} <a href="/admin#/admin">Open admin</a></div><div v-if="loading" class="card-grid"><div v-for="n in 4" :key="n" class="server-card skeleton-card" /></div><div v-else-if="!servers.length" class="empty-state"><div class="empty-icon">⌁</div><h2>No servers yet</h2><p>Add a server in the admin console to start monitoring.</p></div><div v-else class="card-grid"><ServerCard v-for="server in servers" :key="server.id" :server="server" :network-names="networkNames" :show-charts="themeOptions.showCharts" :show-three-net="showThreeNet" /></div></section></template>
